using System.Text;
using Spyro.Editor.Core.Editing;
using static Cases;

// Literal expectations are not generated by the codec under test.
internal static class MaterialCodecCases
{
    internal const string ColorJson = "{\"tag\":\"base-floor-color\"}";
    internal const string RetailJson = "{\"tag\":\"retail-terrain-record\",\"sourceVariant\":\"spyro1-usa-retail-mode2-2352-v1\",\"sourceWadEntry\":14,\"textureId\":0}";
    internal const string PairJson = "{\"layout\":\"rectangle-two-triangles-v1\",\"triangle0\":" + RetailJson + ",\"triangle1\":" + ColorJson + "}";
    internal const string Golden = "{\"kind\":\"spyro-native-fresh-level\",\"schema\":2,\"base\":" + BaseJson + ",\"placements\":[" + PlacementJson + "],\"floorMaterials\":" + PairJson + "}";
    internal static NativeFreshLevelDocumentIntent Value() => Document(Wizard()).WithFloorMaterials(
        NativeFreshFloorMaterialsIntent.Create(MaterialIntentCases.Retail(), MaterialIntentCases.Color()));

    internal static void Run()
    {
        Check(Serialize(Value()) == Golden, "exact schema2 literal, field order, no BOM/whitespace/LF");
        var parsed = Parse(Golden);
        Check(parsed.SchemaVersion == 2 && Serialize(parsed) == Golden &&
            parsed.FloorMaterials!.Triangle0 is NativeFreshRetailTerrainMaterialIntent source &&
            source.SourceVariant == MaterialIntentCases.Variant && source.SourceWadEntry == 14 && source.TextureId == 0 &&
            parsed.FloorMaterials.Triangle1.Tag == "base-floor-color", "literal parse retains both tagged slots");
        Check(Serialize(Parse(Canonical)) == Canonical && Serialize(Document(Wizard())) == Canonical &&
            Encoding.UTF8.GetString(NativeId65FreshDocumentCodec.SerializeCanonical(parsed.Base)) == BaseJson,
            "all old aggregate and embedded Base v1 bytes unchanged");
        string reordered = "{\"floorMaterials\":" + PairJson + ",\"placements\":[" + PlacementJson +
            "],\"base\":" + BaseJson + ",\"schema\":2,\"kind\":\"spyro-native-fresh-level\"}";
        Check(Serialize(Parse(" \n" + reordered + "\t")) == Golden, "valid root order/whitespace canonicalized explicitly");
        foreach (var pair in new[]
        {
            NativeFreshFloorMaterialsIntent.Create(MaterialIntentCases.Retail(), MaterialIntentCases.Retail(70)),
            NativeFreshFloorMaterialsIntent.Create(MaterialIntentCases.Retail(70), MaterialIntentCases.Retail()),
            NativeFreshFloorMaterialsIntent.Create(MaterialIntentCases.Retail(), MaterialIntentCases.Retail()),
            NativeFreshFloorMaterialsIntent.Create(MaterialIntentCases.Color(), MaterialIntentCases.Retail(78,127)),
            NativeFreshFloorMaterialsIntent.Create(MaterialIntentCases.Color(), MaterialIntentCases.Color())
        })
        {
            var value = parsed.WithFloorMaterials(pair); string text = Serialize(value);
            Check(Serialize(Parse(text)) == text && Parse(text).SchemaVersion == 2, "ordered/mixed/same/clear schema2 roundtrip");
        }
        foreach (string invalid in new[]
        {
            Golden.Replace("\"schema\":2", "\"schema\":1"),
            Golden.Replace("\"schema\":2", "\"schema\":3"),
            Golden.Replace(",\"floorMaterials\":" + PairJson, ""),
            Golden.Replace(PairJson, "null"), Golden.Replace(PairJson, "[]"),
            Golden.Replace("rectangle-two-triangles-v1", "rectangle-two-triangles-v2"),
            Golden.Replace("\"layout\":\"rectangle-two-triangles-v1\",", ""),
            Golden.Replace("\"triangle0\":" + RetailJson + ",", ""),
            Golden.Replace(",\"triangle1\":" + ColorJson, ""),
            Golden.Replace(RetailJson, "null"), Golden.Replace(ColorJson, "[]"),
            Golden.Replace("retail-terrain-record", "custom-file"),
            Golden.Replace("base-floor-color", "Base-floor-color"),
            Golden.Replace("\"tag\":\"retail-terrain-record\",", ""),
            Golden.Replace("\"sourceVariant\":\"" + MaterialIntentCases.Variant + "\",", ""),
            Golden.Replace("\"sourceWadEntry\":14,", ""), Golden.Replace(",\"textureId\":0", ""),
            Golden.Replace(MaterialIntentCases.Variant, "unknown-retail"),
            Golden.Replace("\"sourceWadEntry\":14", "\"sourceWadEntry\":11"),
            Golden.Replace("\"textureId\":0", "\"textureId\":128"),
            Golden.Replace("\"floorMaterials\":", "\"FloorMaterials\":"),
            Golden.Replace("\"triangle0\":", "\"Triangle0\":"),
            Golden.Replace("\"textureId\":", "\"TextureId\":")
        }) Reject(() => Parse(invalid), "closed version/material shape");

        foreach (string number in new[] { "null", "true", "\"0\"", "0.0", "0e0", "-1", "2147483648", "-2147483649" })
        {
            Reject(() => Parse(Golden.Replace("\"textureId\":0", "\"textureId\":" + number)), "strict texture integer");
            Reject(() => Parse(Golden.Replace("\"sourceWadEntry\":14", "\"sourceWadEntry\":" + number)), "strict entry integer");
        }
        foreach (string injected in new[]
        {
            "\"path\":\"/must-not-read\",", "\"handle\":{},", "\"sha256\":\"claimed\",",
            "\"runtimeApproved\":true,", "\"uvScale\":1,", "\"surfacePhysics\":\"lava\",",
            "\"tag\":\"retail-terrain-record\",", "\"ta\\u0067\":\"retail-terrain-record\","
        }) Reject(() => Parse(Golden.Replace(RetailJson, "{" + injected + RetailJson[1..])), "unknown/certificate/duplicate material field");
        Reject(() => Parse(Golden.Replace(ColorJson, "{\"tag\":\"base-floor-color\",\"textureId\":0}")), "base-color refuses retail fields");
        Reject(() => Parse(Golden.Replace(PairJson, "{\"triangle2\":" + ColorJson + "," + PairJson[1..])), "exactly two fixed slots");
        Reject(() => Parse(Golden.Replace(PairJson, "{\"triangle0\":" + RetailJson + "," + PairJson[1..])), "duplicate slot");
        Reject(() => Parse(Golden.Replace(PairJson, "{\"triangl\\u00650\":" + RetailJson + "," + PairJson[1..])), "escaped duplicate slot");
        Reject(() => Parse(Golden.Replace("\"floorMaterials\":", "\"floorMaterials\":" + PairJson + ",\"floorMaterials\":")), "duplicate root materials");
        Reject(() => Parse(Golden[..^1] + ",}"), "no trailing comma");
        Reject(() => Parse("/* no */" + Golden), "no comments");
        Reject(() => NativeFreshLevelDocumentCodec.Parse(new byte[] { 0xEF, 0xBB, 0xBF }.Concat(Encoding.UTF8.GetBytes(Golden)).ToArray()), "no UTF8 BOM");
        Reject(() => NativeFreshLevelDocumentCodec.Parse(Encoding.UTF8.GetBytes(Golden).Concat(new byte[] { 0xFF }).ToArray()), "strict UTF8");
        Check(Serialize(Parse(Golden + new string(' ', 65536 - Encoding.UTF8.GetByteCount(Golden)))) == Golden, "unchanged64KiB inclusive input cap");
        Reject(() => Parse(Golden + new string(' ', 65537 - Encoding.UTF8.GetByteCount(Golden))), "unchanged64KiB overflow refusal");
        string baseAtCap = BaseJson[..^1] + new string(' ', 16384 - Encoding.UTF8.GetByteCount(BaseJson)) + "}";
        Check(Serialize(Parse(Golden.Replace(BaseJson, baseAtCap))) == Golden, "embedded Base independently allows exact16KiB");
        Reject(() => Parse(Golden.Replace(BaseJson, baseAtCap[..^1] + " }")), "embedded Base refuses16KiB plus1 despite outer64KiB budget");
        var many = parsed.WithContent(parsed.Base, Enumerable.Range(1,128).Select(i => Wizard(i.ToString("x32"))));
        Check(Parse(Serialize(many)).Placements.Count == 128, "two slots coexist with full ordered128 IDs");
        var bytes = NativeFreshLevelDocumentCodec.SerializeCanonical(parsed); bytes[0] = 0;
        Check(Serialize(parsed) == Golden, "serialization copy mutation never changes intent");
    }
}
